import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BEmfQga0.js";const h=JSON.parse('{"title":"Repository Structure","description":"","frontmatter":{},"headers":[],"relativePath":"development/repository-structure.md","filePath":"development/repository-structure.md","lastUpdated":1788692144000}'),p={name:"development/repository-structure.md"};function r(o,e,i,l,c,d){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="repository-structure" tabindex="-1">Repository Structure <a class="header-anchor" href="#repository-structure" aria-label="Permalink to &quot;Repository Structure&quot;">​</a></h1><p>The LightRSI repository is organized around the plugin platform and its components.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LightRSI/</span></span>
<span class="line"><span>├── components/</span></span>
<span class="line"><span>│   ├── adapters/                # Host-specific integration</span></span>
<span class="line"><span>│   │   ├── openclaw/            #   OpenClaw native plugin adapter</span></span>
<span class="line"><span>│   │   ├── codex/               #   Codex CLI proxy + hooks adapter</span></span>
<span class="line"><span>│   │   ├── claude-code/         #   Claude Code gateway + MCP adapter</span></span>
<span class="line"><span>│   │   └── deepseek-harness/    #   DeepSeek Harness compatibility adapter</span></span>
<span class="line"><span>│   ├── products/</span></span>
<span class="line"><span>│   │   ├── cli/                 #   Shared lightrsi CLI</span></span>
<span class="line"><span>│   │   └── mcp/                 #   Shared MCP recovery server</span></span>
<span class="line"><span>│   ├── presets/</span></span>
<span class="line"><span>│   │   └── tokenpilot/          #   TokenPilot composition preset</span></span>
<span class="line"><span>│   └── packages/</span></span>
<span class="line"><span>│       ├── foundation/          #   Shared contracts and runtime primitives</span></span>
<span class="line"><span>│       └── features/            #   Reduction, eviction, cleaner, memory, stabilizer</span></span>
<span class="line"><span>├── docs/                        # Public-facing notes and helpers</span></span>
<span class="line"><span>├── website/                     # This documentation site</span></span>
<span class="line"><span>├── figs/                        # Images for README</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><p>Benchmark tasks, runners, profiles, and analysis are maintained in the separate <a href="https://github.com/Xubqpanda/TokenPilot" target="_blank" rel="noreferrer">TokenPilot experiment repository</a>.</p><h2 id="key-directories" tabindex="-1">Key Directories <a class="header-anchor" href="#key-directories" aria-label="Permalink to &quot;Key Directories&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Directory</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>components/packages/foundation/kernel/</code></td><td style="text-align:left;">Types, interfaces, events — the contract layer</td></tr><tr><td style="text-align:left;"><code>components/packages/foundation/runtime-core/</code></td><td style="text-align:left;">Plugin execution engine</td></tr><tr><td style="text-align:left;"><code>components/packages/features/</code></td><td style="text-align:left;">Stateful processing and policy features</td></tr><tr><td style="text-align:left;"><code>components/adapters/</code></td><td style="text-align:left;">One adapter per host</td></tr><tr><td style="text-align:left;"><code>components/products/cli/</code></td><td style="text-align:left;">The <code>lightrsi</code> CLI</td></tr><tr><td style="text-align:left;"><code>components/products/mcp/</code></td><td style="text-align:left;">Shared MCP server</td></tr></tbody></table><h2 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h2><p>The repository uses pnpm workspaces. See <code>pnpm-workspace.yaml</code> for the full list.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/LightRSI/development/local-development">Local Development</a></li><li><a href="/LightRSI/development/build-and-test">Build and Test</a></li><li><a href="/LightRSI/development/contributing">Contributing</a></li></ul>`,10)])])}const m=t(p,[["render",r]]);export{h as __pageData,m as default};
